McfgAllocations = None
# Retain the last selected base for existing users such as PciLibTest.py.
McfgBassAddress = None

def GetBaseAddress (Bus = 0, Segment = 0):
  """Select an ECAM allocation by segment and absolute bus number."""

  global McfgAllocations, McfgBassAddress

  from EfiPy2.Lib.Acpi.AcpiRetrieve   import ExtractTable
  from EfiPy2.Lib.Acpi.AcpiMcfgParser import AcpiMcfgParser

  if not 0 <= Bus <= 0xFF or not 0 <= Segment <= 0xFFFF:
    raise ValueError ('Invalid PCI segment or bus number.')
  if McfgAllocations is None:
    AcpiRaw = ExtractTable (b'MCFG', 0)
    AcpiObj, _ = AcpiMcfgParser (AcpiRaw)
    McfgAllocations = AcpiObj.McfgDesc

  for Desc in McfgAllocations:
    if (Desc.PciSegmentGroupNumber == Segment and
        Desc.StartBusNumber <= Bus <= Desc.EndBusNumber):
      McfgBassAddress = Desc.BaseAddress
      return Desc.BaseAddress
  raise ValueError (f'No MCFG allocation for segment {Segment:04x}, bus {Bus:02x}.')

def GetPciEcam (Bus = 0, Device = 0, Function = 0, Segment = 0):

  import EfiPy2.MdePkg.IndustryStandard.Pci as pci

  if not 0 <= Device <= 31 or not 0 <= Function <= 7:
    raise ValueError ('Invalid PCI device or function number.')
  BaseAddress = GetBaseAddress (Bus, Segment)
  return BaseAddress + pci.PCI_ECAM_ADDRESS (Bus, Device, Function, 0)
